<script setup lang="ts">
/**
 * The Drafts list context: one Ash coverage line with a quiet `New draft`
 * action, the in-flow recovery and error lines, and one row per local draft.
 * Rows are not threads, so they use `ContextRowList` (the 36px list-row
 * anatomy and its keyboard model: J/K, arrows, Home, End, roving tabindex).
 *
 * Opening a draft is the app's decision (`open`): a reply draft goes to its
 * source conversation, a new message to the inline compose card. This
 * component only lists drafts and reports which one was chosen. The editor
 * itself is never mounted here (`DraftEditorCore` lives in the card and the
 * docked reply composer), so the list shows only while no editor covers it.
 *
 * Rows are recipient (Title; Ash `(no recipient)`), subject (Ash
 * `(no subject)`), a quiet `Reply` word for reply drafts and the compact
 * updated time. The revision is a row title, and a word (`Conflict · revision
 * N`, Amber Notice) only while that draft is the one in conflict.
 */
import { computed, ref } from 'vue';
import type { DraftRef, DraftSummary, MailError } from '../lib/ipc/client';
import { compactDateLabel, fullDateLabel, machineDateTime } from '../lib/browsing-dates';
import ContextRowList from './ContextRowList.vue';
import DraftAlerts from './DraftAlerts.vue';

const LOCAL_LINE = 'Local to this device · never sent';
const LOCAL_DETAIL = 'Drafts are local to this device and account. No drafts are sent to a mail provider.';

interface DraftItem { key: string; draft: DraftSummary }

const props = defineProps<{
  summaries: readonly DraftSummary[];
  /** The remembered current row (restored after a reader or editor round trip). */
  activeKey: string | null;
  /** The editor's draft, to mark the one in conflict. */
  activeRef: DraftRef | null;
  conflict: boolean;
  suspendedEditor: boolean;
  /** Opening or creating is disabled while the editor is closing or switching. */
  busy: boolean;
  createError: MailError | null;
  listError: MailError | null;
  subscriptionError: MailError | null;
  closeError: string | null;
  closeRetryAvailable: boolean;
  closeSetupError: string | null;
}>();

const emit = defineEmits<{
  newDraft: [];
  open: [draft: DraftSummary];
  'update:activeKey': [key: string];
  retryDraftSubscription: [];
  retryClose: [];
  retryCloseSetup: [];
}>();

/** Stable row key for one draft; the app uses it to remember the current row. */
function draftKey(ref: DraftRef): string {
  return `${ref.accountId}:${ref.draftId}`;
}

const items = computed<DraftItem[]>(() => props.summaries.map(draft => ({ key: draftKey(draft.ref), draft })));

/** The revision is shown as a word only while this very draft is in conflict. */
function inConflict(ref: DraftRef): boolean {
  return props.conflict && !!props.activeRef && props.activeRef.accountId === ref.accountId && props.activeRef.draftId === ref.draftId;
}

function rowTitle(item: DraftItem): string {
  return `Revision ${item.draft.revision} · ${item.draft.source.kind === 'reply' ? 'Reply' : 'New message'}`;
}

const list = ref<{ focusRow: (key: string | null, options?: { preventScroll?: boolean }) => Promise<void> } | null>(null);
const paneEl = ref<HTMLElement | null>(null);

/** Focus the current row, or the pane itself when there is no row to take it. */
async function focusRow(options: { preventScroll?: boolean } = {}): Promise<void> {
  if (list.value) await list.value.focusRow(props.activeKey, options);
  else paneEl.value?.focus(options);
}
defineExpose({ focusRow, el: paneEl });
</script>

<template>
  <div ref="paneEl" class="context-pane drafts-pane" data-test="drafts-pane" tabindex="-1">
    <!-- Recovery and error lines are in flow above the rows, never hidden. -->
    <DraftAlerts
      :suspended-editor="suspendedEditor"
      :close-error="closeError"
      :close-setup-error="closeSetupError"
      :close-retry-available="closeRetryAvailable"
      :list-error="listError"
      :subscription-error="subscriptionError"
      :create-error="createError"
      @retry-draft-subscription="emit('retryDraftSubscription')"
      @retry-close="emit('retryClose')"
      @retry-close-setup="emit('retryCloseSetup')"
    />

    <!-- The one standing local-only line; the sentence is its title and hidden text. -->
    <div class="context-coverage">
      <p class="cached-coverage" role="note" data-test="drafts-coverage" :title="LOCAL_DETAIL">{{ LOCAL_LINE }}<span class="visually-hidden">. {{ LOCAL_DETAIL }}</span></p>
      <button type="button" class="drawer-quiet" data-test="new-draft" :disabled="busy" @click="emit('newDraft')">New draft</button>
    </div>

    <p v-if="!items.length" class="list-state" data-test="draft-list-empty">No local drafts.</p>
    <ContextRowList
      v-else
      ref="list"
      data-test="draft-list"
      :items="items"
      label="Local drafts"
      :active-key="activeKey"
      :disabled="busy"
      :row-title="rowTitle"
      :open-test-id="(item: DraftItem) => `open-draft-${item.draft.ref.draftId}`"
      @update:active-key="emit('update:activeKey', $event)"
      @open="emit('open', $event.draft)"
    >
      <template #primary="{ item }"><span class="context-subject" :class="{ 'drawer-empty': !item.draft.to }">{{ item.draft.to || '(no recipient)' }}</span></template>
      <template #secondary="{ item }"><span class="draft-subject" :class="{ 'drawer-empty': !item.draft.subject }">{{ item.draft.subject || '(no subject)' }}</span></template>
      <template #trailing="{ item }">
        <span v-if="inConflict(item.draft.ref)" class="activity-status tone-warn" data-test="draft-row-conflict">Conflict · revision {{ item.draft.revision }}</span>
        <span v-if="item.draft.source.kind === 'reply'" class="draft-reply">Reply</span>
        <time class="draft-date row-time" :datetime="machineDateTime(item.draft.updatedAt)" :title="fullDateLabel(item.draft.updatedAt)">{{ compactDateLabel(item.draft.updatedAt) }}</time>
      </template>
    </ContextRowList>
  </div>
</template>
<script setup lang="ts" generic="T extends { key: string }">
/**
 * Rows of a list context whose rows are not threads (Reminders, Drafts):
 * the Conversation Row geometry of DESIGN.md with slots instead of sender,
 * subject and snippet.
 *
 * - 36px rows on 12px type, inset 6px from both pane edges, a 44px gutter
 *   (`lead`), the text on the 50px content inset, the trailing slot about 25px
 *   from the pane edge. No row borders: rows are separated by rhythm alone.
 * - The current row is the one signal: Focus Stone fill plus the 4px Dusk
 *   Lavender bar, and `aria-current` on its item, like InboxList.
 * - One real button per row (`primary`) is the row's action and its keyboard
 *   marker. `secondary` is a quiet Ash line beside it, outside the button's
 *   name. ArrowUp/ArrowDown or J/K, Home and End move between rows through
 *   `useDrawerRows` (roving tabindex, no wrap; editable targets, IME and
 *   modified keys are ignored). Enter and Space stay native. The trailing slot
 *   and the row `actions` are not rows: they keep native Tab and Enter and
 *   stay Tab-reachable. Escape is the app's.
 * - Clicking the row outside any control opens it, like an Inbox row.
 * - `note` is an exception line under its row (Coral or Amber), only where one
 *   applies.
 */
import { computed, nextTick, ref } from 'vue';
import { useDrawerRows } from '../composables/useDrawerRows';

const props = defineProps<{
  items: readonly T[];
  /** The list's accessible name. */
  label: string;
  /** The remembered current row key (restored after a reader round trip). */
  activeKey?: string | null;
  /** Visually hidden verb that starts the open button's accessible name. */
  openVerb?: string;
  /** Hover title of the open button (for example a revision). */
  rowTitle?: (item: T) => string | undefined;
  rowTestId?: (item: T) => string | undefined;
  /** Test hook of the open button (the row's marker element). */
  openTestId?: (item: T) => string | undefined;
  /** Rows cannot be opened while true (an editor transition is running). */
  disabled?: boolean;
}>();
const emit = defineEmits<{ open: [item: T]; 'update:activeKey': [key: string] }>();

const listEl = ref<HTMLElement | null>(null);
const rows = useDrawerRows({ keys: () => props.items.map(item => item.key), initial: () => props.activeKey ?? null });
/** The current row: the remembered one, else the first (the Tab stop). */
const currentKey = computed(() => {
  const keys = props.items.map(item => item.key);
  return rows.active.value !== null && keys.includes(rows.active.value) ? rows.active.value : keys[0] ?? null;
});

/** Opening a row also makes it the remembered current row, so Back lands on it. */
function open(item: T): void {
  if (props.disabled) return;
  emit('update:activeKey', item.key);
  emit('open', item);
}

function onRowClick(event: MouseEvent, item: T): void {
  const target = event.target;
  if (target instanceof Element && target.closest('button, a, input, select, textarea, label')) return;
  open(item);
}

/** Focus one row's button (or the list itself when there is no row to take it). */
async function focusRow(key: string | null, options: { preventScroll?: boolean } = {}): Promise<void> {
  await nextTick();
  const button = key === null ? null : [...(listEl.value?.querySelectorAll<HTMLElement>('[data-drawer-row]') ?? [])]
    .find(el => el.dataset.drawerRow === key) ?? null;
  const first = listEl.value?.querySelector<HTMLElement>('[data-drawer-row]') ?? null;
  (button ?? first ?? listEl.value)?.focus({ preventScroll: options.preventScroll ?? false });
}

defineExpose({ focusRow, el: listEl });
</script>

<template>
  <ul ref="listEl" class="context-list" role="list" :aria-label="label" tabindex="-1" @keydown="rows.onKeydown">
    <li
      v-for="item in items"
      :key="item.key"
      class="context-item"
      role="listitem"
      :aria-current="currentKey === item.key ? 'true' : undefined"
      :data-test="rowTestId?.(item)"
    >
      <div class="context-row" :class="{ focused: currentKey === item.key }" @click="onRowClick($event, item)">
        <span class="context-row-lead"><slot name="lead" :item="item" /></span>
        <button
          type="button"
          class="context-row-main"
          v-bind="rows.rowAttrs(item.key)"
          :title="rowTitle?.(item)"
          :data-test="openTestId?.(item)"
          :disabled="disabled || undefined"
          @focus="emit('update:activeKey', item.key)"
          @click="open(item)"
        >
          <span class="visually-hidden">{{ `${openVerb ?? 'Open'} ` }}</span>
          <span class="context-row-primary"><slot name="primary" :item="item" /></span>
        </button>
        <span class="context-row-secondary"><slot name="secondary" :item="item" /></span>
        <span class="context-row-actions"><slot name="actions" :item="item" /></span>
        <span class="context-row-trailing"><slot name="trailing" :item="item" /></span>
      </div>
      <slot name="note" :item="item" />
    </li>
  </ul>
</template>

  listOperationGroups(request: ListOperationGroupsRequest): Promise<OperationGroupPage>;
  /**
   * One partial group Undo attempt for the whole group; durable per-member cancel/
   * compensate/skip decisions. Same-request retries return the same decisions;
   * rejects with `undo_unavailable` when expired, superseded or already undone.
   */
  undoOperationGroup(command: UndoOperationGroup): Promise<GroupUndoReceipt>;
  /** Registers a change listener; resolves with an unsubscribe function. */
  subscribe(listener: () => void): Promise<() => void>;
  /** Authoritative fixture-vs-Gmail mode and connection/sync state. */
  getAccountStatus(): Promise<AccountStatus>;
  /** Enqueues a connect (OAuth) attempt; resolves on acceptance, not on success. */
  connectAccount(): Promise<void>;
  /** Resolves only after credentials and local account/cache data are cleared. */
  disconnectAccount(): Promise<void>;
  /** Enqueues an incremental sync; resolves on acceptance, not on completion. */
  requestSync(): Promise<void>;
  listDrafts(): Promise<DraftSummary[]>;
  getDraft(ref: DraftRef): Promise<Draft>;
  createDraft(command: CreateDraft): Promise<DraftReceipt>;
  saveDraft(command: SaveDraft): Promise<DraftReceipt>;
  deleteDraft(command: DeleteDraft): Promise<DraftDeleteReceipt>;
  subscribeDrafts(listener: () => void): Promise<() => void>;
  subscribeAppClose(listener: (request: AppCloseRequest) => void): Promise<() => void>;
  completeAppClose(requestId: string): Promise<void>;
  cancelAppClose(requestId: string): Promise<void>;
}

export function isMailErrorShape(value: unknown): value is MailError {
  if (typeof value !== 'object' || value === null || !('kind' in value)) return false;
  const kind = (value as { kind: unknown }).kind;
  if (typeof kind !== 'string') return false;
  switch (kind) {
    case 'not_found':
    case 'request_id_conflict':
    case 'storage_unavailable':
    case 'profile_in_use':
    case 'read_only':
    case 'not_configured':
    case 'auth_required':
    case 'auth_cancelled':
    case 'auth_failed':
    case 'secrets_unavailable':
    case 'network_unavailable':
    case 'rate_limited':
    case 'provider_unavailable':
    case 'invalid_provider_response':
    case 'busy':
    case 'permission_required':
    case 'provider_rejected':
    case 'outcome_unknown':
    case 'reply_unavailable':
      return true;
    case 'draft_conflict':
      return typeof (value as unknown as { currentRevision: unknown }).currentRevision === 'number';
    case 'invalid_request':
      return typeof (value as unknown as { field: unknown }).field === 'string';
    case 'undo_unavailable':
      return UNDO_UNAVAILABLE_REASONS.includes(
        (value as unknown as { reason: unknown }).reason as string,
    );
import { computed, onBeforeUnmount, onMounted, ref, watch, type ComputedRef } from 'vue';
import type { ClientMode } from '../lib/ipc';
import type {
  AppCloseRequest,
  CreateDraft,
  DeleteDraft,
  Draft,
  DraftContent,
  DraftRef,
  DraftReceipt,
  DraftSource,
  DraftSummary,
  MailClient,
  MailError,
  SaveDraft,
} from '../lib/ipc/client';

const EMPTY_CONTENT: DraftContent = { to: '', cc: '', subject: '', bodyText: '' };
const DEBOUNCE_MS = 300;

function copyContent(content: DraftContent): DraftContent {
  return { to: content.to, cc: content.cc, subject: content.subject, bodyText: content.bodyText };
}

function sameContent(left: DraftContent, right: DraftContent): boolean {
  return left.to === right.to && left.cc === right.cc && left.subject === right.subject && left.bodyText === right.bodyText;
}

function requestId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  return `ui-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

function errorMessage(error: MailError): string {
  switch (error.kind) {
    case 'draft_conflict': return `This draft changed elsewhere (saved revision ${error.currentRevision}). Your exact text is preserved.`;
    case 'invalid_request': return `The local draft was not saved (invalid ${error.field}). Correct the field and save again.`;
    case 'reply_unavailable': return 'Reply preparation is unavailable because complete, current message headers could not be verified. No draft was created.';
    case 'not_found': return 'This draft is no longer available in the current account.';
    case 'auth_required': return 'The account is unavailable. Local drafts remain on this device and can be reopened after reconnecting the same account.';
    case 'profile_in_use': return 'The local profile is in use by another window. The text remains in this editor.';
    case 'request_id_conflict': return 'The save request conflicted with an earlier request. The text remains in this editor.';
    case 'storage_unavailable': return 'Local storage did not confirm this save. The text remains in this editor; retry safely.';
    default: return 'The local draft operation was not confirmed. The text remains in this editor.';
  }
}

export function useDrafts(client: MailClient, accountId: ComputedRef<string | null>, mode: ClientMode) {
  const summaries = ref<DraftSummary[]>([]);
  const listError = ref<MailError | null>(null);
  const draftSubscriptionError = ref<MailError | null>(null);
  const activeRef = ref<DraftRef | null>(null);
  const activeSource = ref<DraftSource | null>(null);
  const content = ref<DraftContent>(copyContent(EMPTY_CONTENT));
  const revision = ref(0);
  const acknowledged = ref<DraftContent>(copyContent(EMPTY_CONTENT));
  const hasReceipt = ref(false);
  const creating = ref(false);
  const saving = ref(false);
  const conflict = ref(false);
  const error = ref<MailError | null>(null);
  const createError = ref<MailError | null>(null);
  const deleting = ref(false);
  const closingForWindow = ref(false);
  const closeError = ref<string | null>(null);
  const closeRetryAvailable = ref(false);
  const confirmDiscard = ref(false);
  const discardBusy = ref(false);
  const confirmReload = ref(false);
  const copyPending = ref(false);
  const recoveryRequired = ref(false);
  const copyRetryEnvelope = ref<CreateDraft | null>(null);
  const transitioning = ref(false);
  const closeSetupError = ref<string | null>(null);
  const deletePending = ref(false);
  const isVisible = computed(() => !!activeRef.value && activeRef.value.accountId === accountId.value);
  const dirty = computed(() => !!activeRef.value && !sameContent(content.value, acknowledged.value));
  const canCancelReplyPreparation = computed(() => !!activeRef.value && !activeRef.value.draftId
    && activeSource.value?.kind === 'reply' && !hasReceipt.value && !dirty.value
    && !saving.value && !deleting.value && !copyPending.value);
  const hasUnsavedWork = computed(() => creating.value || saving.value || deleting.value || deletePending.value || copyPending.value || !!copyRetryEnvelope.value || recoveryRequired.value || dirty.value || !!retryEnvelope || !!createEnvelope);
  const statusLabel = computed(() => {
    if (conflict.value) return 'Conflict — edits preserved';
    if (error.value || createError.value) return 'Save not confirmed';
    if (creating.value) return 'Creating local draft…';
    if (saving.value || dirty.value || retryEnvelope || createEnvelope) return 'Saving locally…';
    if (!activeRef.value) return '';
    if (!hasReceipt.value) return mode === 'browser-preview' ? 'Loaded from preview memory (non-durable)' : 'Draft loaded from this device';
    return mode === 'browser-preview' ? 'Saved in preview memory (non-durable)' : 'Saved locally';
  });

  let listToken = 0;
  let generation = 0;
  let saveLaneGeneration = 0;
  let reloadAttempt = 0;
  let timer: ReturnType<typeof setTimeout> | null = null;
  let unsubscribeDrafts: (() => void) | null = null;
  let unsubscribeClose: (() => void) | null = null;
  let detached = false;
  let listSubscriptionAttempt: Promise<void> | null = null;
  let closeSubscriptionAttempt: Promise<void> | null = null;
  let inFlight: Promise<boolean> | null = null;
  let flushPromise: Promise<boolean> | null = null;
  let flushOwner: { generation: number; lane: number } | null = null;
  let retryEnvelope: SaveDraft | null = null;
  let createEnvelope: CreateDraft | null = null;
  let copyRetryOwner: { generation: number; accountId: string; draftId: string } | null = null;
  let copyPromise: Promise<boolean> | null = null;
  let deleteRetryEnvelope: DeleteDraft | null = null;
  let deletePromise: Promise<boolean> | null = null;
  let discardIntentToken = 0;
  let discardIntent: { token: number; generation: number; ref: DraftRef } | null = null;
  let createPromise: Promise<boolean> | null = null;
  let lastCloseRequestId: string | null = null;
  let closeToken = 0;
  let completionDispatched = false;

  function clearTimer(): void {
    if (timer) clearTimeout(timer);
    timer = null;
  }

  function retireSaveLane(): void {
    saveLaneGeneration += 1;
    clearTimer();
    inFlight = null;
    saving.value = false;
    retryEnvelope = null;
  }

  function clearEditor(): void {
    generation += 1;
    saveLaneGeneration += 1;
    reloadAttempt += 1;
    clearTimer();
    activeRef.value = null;
    activeSource.value = null;
    content.value = copyContent(EMPTY_CONTENT);
    acknowledged.value = copyContent(EMPTY_CONTENT);
    revision.value = 0;
    hasReceipt.value = false;
    creating.value = false;
    saving.value = false;
    conflict.value = false;
    error.value = null;
    createError.value = null;
    deleting.value = false;
    confirmDiscard.value = false;
    discardBusy.value = false;
    discardIntentToken += 1;
export type DraftRef = { accountId: string, draftId: string, };

export type DraftContent = { to: string, cc: string, subject: string, bodyText: string, };

export type DraftSource = { "kind": "new_message" } | { "kind": "reply", conversation: ConversationRef, sourceMessageId: string, };

export type DraftReplyLink = { conversation: ConversationRef, sourceMessageId: string, messageId: string, references: Array<string>, };

export type Draft = { ref: DraftRef, revision: number, createdAt: string, updatedAt: string, content: DraftContent, source: DraftSource, replyLink: DraftReplyLink | null, };

export type DraftSummary = { ref: DraftRef, revision: number, updatedAt: string, subject: string, to: string, source: DraftSource, };

export type DraftReceipt = { ref: DraftRef, revision: number, savedAt: string, };

export type DraftDeleteReceipt = { ref: DraftRef, deletedAt: string, };

