.activity-action,
.drawer-date {
  flex: none;
  white-space: nowrap;
}

.drawer-date,
.drawer-empty {
  color: var(--text-secondary);
}

.drawer-date {
  font-variant-numeric: tabular-nums;
}

.activity-status {
  flex: none;
  white-space: nowrap;
}

/* Ghost buttons in a drawer: quiet Ash text, Paper White Title weight for the
   one action, Focus Stone for a choice. Their text lines up with the content
   edge; the 8px padding is only the hit target. */
.drawer-quiet,
.drawer-action,
.drawer-primary,
.drawer-chip {
  border: 0;
  border-radius: 4px;
  padding: 4px 8px;
  background: transparent;
  font: inherit;
}

.drawer-quiet {
  color: var(--text-secondary);
}

.drawer-action {
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

.drawer-chip {
  color: var(--text-secondary);
}

.drawer-chip[aria-pressed='true'] {
  background: var(--focus-fill);
  color: var(--text-primary);
}

.drawer-primary {
  background: var(--focus-fill);
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

.drawer-quiet:hover:not(:disabled),
.drawer-action:hover:not(:disabled),
.drawer-chip:hover:not(:disabled) {
  background: var(--focus-fill);
  color: var(--text-primary);
}

.drawer-primary:hover:not(:disabled) {
  background: var(--focus-fill);
  box-shadow: inset 0 0 0 1px var(--text-secondary);
}

/* On a hovered row the fill already equals the button hover fill: add the ring. */
.drawer-row .drawer-quiet:hover:not(:disabled) {
  box-shadow: inset 0 0 0 1px var(--text-secondary);
}

.drawer-line > .drawer-quiet:first-child,
.drawer-line > .drawer-action:first-child,
.drawer-row-actions > .drawer-quiet:first-child {
  margin-left: -8px;
}

.drawer-alert .drawer-quiet {
  margin-left: 6px;
}

 * ~700px list, ~115px at the 1030px window, 96px at its floor. Only if a row
 * still cannot fit its subject/snippet floor does that row's sender shrink
 * further (to 72px); the metadata keeps its full content.
 */
.inbox-row,
.context-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 36px;
  margin: 0 6px;
  padding: 0 18px 0 44px;
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  color: var(--text-primary);
  cursor: pointer;
  /* Anchors the gutter controls and the row action disclosure panel. */
  position: relative;
}

.inbox-row:focus,
.context-row:focus {
  outline: none;
}

/* Focus: Focus Stone fill plus a 4px Dusk Lavender bar on the fill's own edge. */
.inbox-row.focused,
.context-row.focused {
  background: var(--focus-fill);
  box-shadow: inset 4px 0 0 var(--focus-accent);
}

/* Hover never changes focus or read state; it only lifts and reveals controls. */
.inbox-row:not(.focused):hover,
.context-row:not(.focused):hover {
  background: rgba(255, 255, 255, 0.03);
}

